using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
// Position-controlled integration, not manual or physical driving verification.
public sealed class PassengerCareProbe:MonoBehaviour {
 DriveSession s;int checks;readonly StringBuilder report=new StringBuilder();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerCareTest")>=0)new GameObject("Passenger care integration").AddComponent<PassengerCareProbe>();}
 void Check(bool ok,string reason){checks++;report.AppendLine((ok?"PASS ":"FAIL ")+reason);Debug.Log((ok?"PASS ":"FAIL ")+reason);if(!ok)throw new Exception(reason);}
 void Pose(Vector3 point,Vector3 direction){s.taxi.body.position=point+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();}
 void Stop(int index){var p=s.jobs.stops[index];Pose(p.Kerb,p.Direction);}
 void Fresh(){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);s.business.passengers.Clear();s.business.enabledCampaign=true;s.business.useV2=true;s.business.preparing=false;s.paused=false;Time.timeScale=1;s.jobs.ClearForDay();s.law.ids=new PrototypeIds(Guid.NewGuid().ToString("N"));s.law.ledger=new LawLedger();s.law.tripId="";}
 JobOffer Offer(){return new JobOffer{pickup=0,drop=3,fare=5000,seconds=120,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3])};}
 void Board(DrunkRideCase kind){var j=s.jobs;j.ForcedRideCase=kind;var o=Offer();j.offers[0]=o;Stop(o.pickup);Check(j.Accept(0)&&j.trip.State==TripState.ToPickup,"accept "+kind);Check(j.Interact()&&j.trip.State==TripState.OnTrip,"board "+kind);Check(j.StartSatisfaction==o.requiredScore-j.StartDeficit+3,"clean3 baseline once "+kind);var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(saved.version==3&&saved.live!=null&&saved.live.jobs.trip.state==TripState.OnTrip&&saved.live.jobs.drunk.identity==j.DrunkRide.identity,"boarding immediately persists stable active seed "+kind);}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();bool ok=false;try{Run();ok=true;}catch(Exception error){report.AppendLine(error.ToString());Debug.LogException(error);}if(ok&&Array.IndexOf(Environment.GetCommandLineArgs(),"-scoreCapture")>=0)yield return CaptureScores();Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/passenger-care-integration.txt",report.ToString()+"\nchecks="+checks+"\n");Debug.Log("PASSENGER_CARE_INTEGRATION_"+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);}
 void Run(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var c in s.traffic.cars){c.Recycle();c.enabled=false;}
  CheckWaitingPopulation();
  Fresh();s.jobs.offers[1]=s.jobs.offers[2]=null;var idle=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(idle);Check(s.jobs.trip.State==TripState.Idle&&s.jobs.current==null&&s.jobs.DrunkRide==null&&s.jobs.offers[1]==null&&s.jobs.offers[2]==null,"fresh idle JsonUtility roundtrip preserves nullable passenger and empty offers");
  var first=Offer();s.jobs.offers[0]=first;Stop(first.pickup);Check(s.jobs.Accept(0),"first pickup pre-board snapshot");var pickup=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(pickup);Check(s.jobs.trip.State==TripState.ToPickup&&s.jobs.current!=null&&s.jobs.DrunkRide==null&&s.jobs.RequestReward==null,"first ToPickup JsonUtility roundtrip has no fake drunk/reward");
  foreach(var kind in new[]{DrunkRideCase.Normal,DrunkRideCase.Vomit,DrunkRideCase.Sleepy,DrunkRideCase.Both}){Fresh();Board(kind);var j=s.jobs;bool vomit=kind==DrunkRideCase.Vomit||kind==DrunkRideCase.Both;bool sleepy=kind==DrunkRideCase.Sleepy||kind==DrunkRideCase.Both;j.DrunkRide.Advance(119,.8f);j.trip.Tick(119);Check(j.DrunkRide.Vomited==vomit&&j.Cleanliness==100,"vomit waits until disembark "+kind);Stop(j.current.drop);Check(j.Interact(),"first valid arrival "+kind);int expected=j.RequestReward.Total;
   if(sleepy){var arrived=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(arrived.live.jobs.trip.arrivalLocked&&arrived.live.jobs.drunk.Waiting,"first wake attempt immediate checkpoint "+kind);Check(j.Active&&j.DrunkRide.Waiting&&j.trip.Remaining==1,"first arrival freezes deadline "+kind);Check(!s.services.CanUse(4)&&!j.Accept(1),"wake wait blocks services/new calls "+kind);int frozenScore=j.ScoreView.value;s.manners.Deduct("wake-score",2,"기상 대기 후 운전 변화",0);Check(j.ScoreView.value==frozenScore,"waiting HUD keeps frozen arrival score "+kind);var payload=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));string id=s.law.tripId;j.RestoreLive(payload);Check(j.DrunkRide.Waiting&&s.law.tripId==id&&j.RequestReward.Total==expected,"active save roundtrip no reroll "+kind);j.DrunkRide.Advance(14.99f,1);j.Interact();Check(j.Active&&s.business.ledger.Rides==0,"wake before15 rejected "+kind);if(kind==DrunkRideCase.Sleepy){j.DrunkRide.Advance(.01f,1);Check(j.Interact(),"manual wake15");}else{j.DrunkRide.Advance(15.01f,1);Pose(j.stops[j.current.drop].Kerb+Vector3.right*15,j.stops[j.current.drop].Direction);j.SendMessage("UpdateCare");Check(j.Active,"auto30 unsafe location blocked");Stop(j.current.drop);j.SendMessage("UpdateCare");Check(!j.Active,"safe return automatic disembark");}}
   Check(j.trip.State==TripState.Complete&&s.business.ledger.Rides==1&&s.business.passengers.Count==1,"single normal settlement "+kind);Check(j.Cleanliness==(vomit?10:98),"clean result "+kind);Check(s.business.passengers[0].paid==expected&&s.business.passengers[0].vomited==vomit,"result preserves frozen fare/vomit "+kind);Check(j.trip.Complete()==0&&!s.business.ledger.Account.Fare(s.law.tripId,expected,1),"no second fare "+kind);
  }
  Fresh();s.business.ledger.Care.Finish("dirty-precondition",true);var offer=Offer();s.jobs.offers[0]=offer;Stop(offer.pickup);Check(s.jobs.Accept(0),"dirty call still allows first encounter");int sequence=s.law.ids.sequence;Check(!s.jobs.Interact()&&s.jobs.AcceptanceLocked&&s.jobs.trip.State==TripState.Idle,"dirty refusal locks acceptance");Check(s.law.ids.sequence==sequence&&s.business.ledger.Rides==0&&s.business.passengers.Count==0,"refusal no tripID/fare/completion");s.jobs.offers[0]=Offer();Check(!s.jobs.Accept(0),"repeat call blocked until wash");
  foreach(var station in s.services.Stations){Pose(station.pump,station.direction);s.services.open=true;double elapsed=s.business.ledger.Elapsed;int cost=s.business.ledger.Account.Expense(1,"wash");Check(s.services.RequestAction(4)&&!s.services.ConfirmAction(false),"wash cancellation "+station.id);Check(s.business.ledger.Elapsed==elapsed&&s.business.ledger.Account.Expense(1,"wash")==cost,"cancel no cost/time "+station.id);Check(s.services.RequestAction(4)&&s.services.ConfirmAction(true),"wash standalone at "+station.id);Check(s.jobs.Cleanliness==100&&!s.jobs.AcceptanceLocked&&s.business.ledger.Elapsed==elapsed+30,"wash30 and unlock "+station.id);}
  Fresh();Board(DrunkRideCase.Sleepy);s.jobs.trip.Tick(121);s.jobs.DrunkRide.Advance(121,.8f);Stop(s.jobs.current.drop);s.jobs.Interact();s.business.ledger.Advance(1201,0);Check(s.business.ledger.State==BusinessState.Closing&&s.jobs.Active,"closing cannot remove sleeping passenger");s.jobs.DrunkRide.Advance(15,1);s.jobs.Interact();Check(s.jobs.trip.State==TripState.Failed&&s.business.ledger.Rides==0&&s.business.ledger.FailedTrips==1,"late before arrival stays zero despite wake");
  Fresh();Stop(0);s.jobs.Generate();int ordinary=0;foreach(var o in s.jobs.offers)if(o!=null&&string.IsNullOrEmpty(o.scenarioId)){ordinary++;Check(!string.IsNullOrEmpty(o.pickupStopId)&&!string.IsNullOrEmpty(o.catalogRevision),"ordinary stable catalog IDs");}Check(s.jobs.stops.Length>12&&ordinary>0,"additional stops reach normal call generation");Check(s.GetComponent<ServiceLawZones>().scenarios.Count==9,"nine fixed courses preserved");
  CheckScoreFlow();CheckScenarioRestore();
 }
 string Notices(DriveNotifications notifications){return string.Join("\n",notifications.VisibleTexts);}

 void CheckScoreFlow(){
  Fresh();var j=s.jobs;var notices=s.GetComponent<DriveNotifications>();notices.RefreshScores();Board(DrunkRideCase.Normal);
  var snapshot=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));snapshot.request.request.kind=RequestKind.Quiet;snapshot.current.requiredScore=85;snapshot.startSatisfaction=76;snapshot.startDeficit=12;snapshot.cleanBonus=3;snapshot.referenceSeconds=100;j.RestoreLive(snapshot);
  notices.RefreshScores();Check(j.ScoreView.value==76&&j.ScoreView.required==85&&s.GetComponent<DriveHUD>().MannerCaption.Contains("76"),"HUD actual S76/R85 rather than M100");Check(notices.VisibleTexts.Length==0,"boarding baseline is not misreported as a score gain");
  Check(s.manners.Deduct("brake-score-test",2,"급제동",0),"actual driving deduction applied");Check(j.ScoreView.value==74&&notices.VisibleText=="급제동 · -2","driving deduction changes gauge and notice immediately before LateUpdate");
  s.requests.request.Accept();s.requests.request.CompleteGoal(true,"actual quiet fulfillment");notices.RefreshScores();Check(j.ScoreView.value==79&&notices.VisibleText=="요청 이행 · +5"&&Notices(notices).Contains("급제동 · -2"),"request fulfillment changes gauge and notification without changing M98");
  var e=new LawEvent{id=s.law.ids.Next("score-test"),day=1,action="신호 위반"};e.Add("signal",LawVerdict.Violation,20);s.law.ledger.Record(e);notices.RefreshScores();Check(s.law.ledger.TotalScore==80&&j.ScoreView.value==79&&notices.VisibleText=="신호 위반 · -20"&&Notices(notices).Contains("요청 이행 · +5"),"actual independent law event updates cumulative gauge/notification only");
  e=new LawEvent{id=s.law.ids.Next("score-test"),day=1,action="양보 준수"};e.Add("yield",LawVerdict.Compliant,0);s.law.ledger.Record(e);notices.RefreshScores();Check(s.law.ledger.TotalScore==81&&notices.VisibleText=="양보 준수 · +1"&&notices.VisibleTexts.Length==4,"actual law recovery updates cumulative UI");
  snapshot=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));j.RestoreLive(snapshot);Check(j.ScoreView.value==79&&j.ScoreView.required==85&&s.manners.ledger.Score==98,"live restore preserves displayed passenger values");
  j.DrunkRide.Advance(100,.8f);j.trip.Tick(100);Stop(j.current.drop);Check(j.Interact(),"score regression actual delivery");var result=s.business.passengers[0];notices.RefreshScores();Check(result.satisfaction==79&&result.startSatisfaction==76&&result.cleanBonus==3&&result.driveDelta==-2&&result.satisfactionDelta==5,"receipt actual stored score includes cleanliness once and drive/request changes");Check(j.ScoreView.value==result.satisfaction&&PassengerScoreView.Recorded(result).value==result.satisfaction,"frozen HUD agrees with stored receipt");Check(result.hasDrivingScore&&result.drivingScore==81,"receipt captures actual cumulative law score at delivery");Check(result.initialFare==5000&&RideReceiptSummary.Money(result).Contains("최종 운임  5,000원"),"receipt preserves initial quote and actual payout");
  var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(saved.passengers[0].satisfaction==79&&saved.passengers[0].drivingScore==81&&saved.passengers[0].hasDrivingScore,"shipping JsonUtility checkpoint preserves satisfaction and law result");
  j.PrepareForNextCall();j.offers[0]=Offer();Stop(j.offers[0].pickup);Check(j.Accept(0),"new pickup after completed score");j.trip.Tick(j.trip.PickupRemaining+1);Check(!j.HasPassengerScore,"expired pickup cannot show previous passenger result or a false boarding");notices.RefreshScores();Check(!Notices(notices).Contains("만족도"),"next unboarded pickup removes stale passenger notices");Fresh();Board(DrunkRideCase.Normal);var failedRequest=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));failedRequest.request.request.kind=RequestKind.Comfort;j.RestoreLive(failedRequest);notices.RefreshScores();s.requests.request.Accept();s.requests.request.CompleteGoal(false,"comfort request not fulfilled");notices.RefreshScores();Check(notices.VisibleText=="요청 미이행 · -10","negative request notice identifies failure rather than fulfillment");
 }
 IEnumerator CaptureScores(){
  Fresh();Board(DrunkRideCase.Normal);var j=s.jobs;var state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));state.request.request.kind=RequestKind.Quiet;state.current.requiredScore=85;state.startSatisfaction=76;state.cleanBonus=3;state.startDeficit=12;state.referenceSeconds=100;j.RestoreLive(state);var notices=s.GetComponent<DriveNotifications>();notices.RefreshScores();s.requests.request.Accept();s.requests.request.CompleteGoal(true,"조용한 응대 이행");notices.RefreshScores();s.manners.Deduct("score-capture",43,"급제동",0);var signal=new LawEvent{id=s.law.ids.Next("score-capture"),day=1,action="신호 위반"};signal.Add("L01",LawVerdict.Violation,20);s.law.ledger.Record(signal);notices.RefreshScores();s.paused=false;Time.timeScale=0;
  foreach(int width in new[]{1280,1600,1920}){Screen.SetResolution(width,width*9/16,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/score-hud-"+width+".png"));yield return new WaitForSecondsRealtime(.3f);}
  Time.timeScale=1;j.DrunkRide.Advance(100,.8f);j.trip.Tick(100);Stop(j.current.drop);j.Interact();var receipt=s.GetComponent<RideCompletionPanel>();receipt.ShowLast();yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/score-receipt.png"));yield return new WaitForSecondsRealtime(.4f);
 }
 void CheckWaitingPopulation(){
  Fresh();s.law.ids=new PrototypeIds("waiting-probe");var j=s.jobs;j.ForcedRideCase=DrunkRideCase.Normal;j.RefreshWaitingPassengers();int visible=0;foreach(var person in j.people)if(person.activeSelf)visible++;Check(visible>0&&visible<j.stops.Length,"waiting population must include empty stops rather than one passenger at every drop-off candidate");
  var saved=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));Check(saved.waitingCaptured&&saved.roadsideWaiting.Length==j.stops.Length,"sparse population stored alongside stable stop IDs");
  int empty=-1,occupied=-1;for(int i=0;i<j.stops.Length;i++){bool call=false;foreach(var offered in j.offers)if(offered!=null&&offered.pickup==i)call=true;if(!call&&!saved.roadsideWaiting[i])empty=i;if(saved.roadsideWaiting[i])occupied=i;}
  Check(empty>=0&&occupied>=0,"catalog includes both empty and waiting roadside destinations");Stop(empty);j.offers=new JobOffer[3];Check(!j.Interact()&&j.trip.State==TripState.Idle,"empty roadside location cannot board an invisible passenger");
  var o=Offer();o.pickup=empty;o.drop=occupied;j.offers[0]=o;Check(j.Accept(0)&&j.HasWaitingPassenger(empty)&&j.people[empty].activeSelf,"accepted call forces pickup passenger even at normally empty stop");Check(j.Interact(),"reserved pickup boards normally");j.RefreshWaitingPassengers();Check(!j.HasWaitingPassenger(empty),"boarded passenger is removed from sidewalk");
  saved=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));j.RestoreLive(saved);for(int i=0;i<j.stops.Length;i++)Check(j.HasWaitingPassenger(i)==j.people[i].activeSelf,"restored waiting render and interaction agree "+i);
  var again=j.CaptureLive();Check(string.Join(",",saved.roadsideWaiting)==string.Join(",",again.roadsideWaiting)&&again.waitingGeneration==saved.waitingGeneration,"save reload preserves sparse population without reroll");
  saved.waitingCaptured=false;saved.roadsideWaiting=null;j.RestoreLive(saved);Check(j.trip.State==TripState.OnTrip&&j.HasWaitingPassenger(j.current.pickup)==false,"old saves without population migrate and retain active passenger");var emptyDrop=j.CaptureLive();emptyDrop.roadsideWaiting[j.current.drop]=false;j.RestoreLive(emptyDrop);int drop=j.current.drop;Stop(drop);Check(j.Interact()&&!j.Active,"delivery at empty drop succeeds without a waiting passenger");j.PrepareForNextCall();j.Generate();j.RefreshWaitingPassengers();Check(!j.HasWaitingPassenger(drop)&&!j.people[drop].activeSelf,"fresh calls do not instantly repopulate an empty drop-off");foreach(var next in j.offers)Check(next==null||next.pickup!=drop,"empty recent drop excluded from automatic call refresh");
 }

 void CheckScenarioRestore(){Fresh();var j=s.jobs;var zones=s.GetComponent<ServiceLawZones>();var course=zones.scenarios.Find(x=>x.id=="PS08");j.ForcedRideCase=DrunkRideCase.Normal;Pose(course.route.path.Position(0),course.route.path.Tangent(0));var offer=new JobOffer{fare=5000,seconds=2000,requiredScore=70};Check(zones.ConfigureScenario(offer,course),"PS08 configured for persistence check");j.offers[0]=offer;Check(j.Accept(0),"PS08 persistence call accepted");Stop(offer.pickup);Check(j.Interact(),"PS08 persistence passenger boarded");var choice=s.GetComponent<ScenarioChoiceSituation>();choice.enabled=false;Pose(course.route.path.Position(0),course.route.path.Tangent(0));j.nav.Refresh();choice.SendMessage("Update");Check(choice.Open&&choice.CanDetour(),"PS08 detour plan available before save");Check(choice.Select(1),"PS08 detour chosen and saved immediately");string plan=choice.Plan;int laws=s.law.ledger.Count;var state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));j.RestoreLive(state);Check(choice.Plan==plan&&!choice.Open&&j.nav.AvoidEdge==course.connector&&j.nav.ObservedEdge==course.alternate,"PS08 selected plan and observed alternate survive real Jobs restore");Check(j.nav.hdRoute!=null&&!j.nav.hdRoute.edges.Contains(course.connector)&&s.law.ledger.Count==laws,"PS08 restored route excludes original connector with no repeated observation");choice.SendMessage("Update");Check(!choice.Open&&s.law.ledger.Count==laws,"PS08 restore does not redisplay exposure or reset plan");
  Fresh();course=zones.scenarios.Find(x=>x.id=="PS09");Pose(course.route.path.Position(0),course.route.path.Tangent(0));offer=new JobOffer{fare=5000,seconds=2000,requiredScore=70};Check(zones.ConfigureScenario(offer,course),"PS09 configured for persistence check");j.offers[0]=offer;Check(j.Accept(0),"PS09 persistence call accepted");Stop(offer.pickup);Check(j.Interact(),"PS09 persistence passenger boarded");choice=s.GetComponent<ScenarioChoiceSituation>();choice.enabled=false;var route=j.nav.hdRoute;int k=route.edges.IndexOf(course.connector);Check(k>0,"PS09 connector has directed approach");Pose(route.path.Position(Mathf.Max(0,route.ends[k-1]-80)),route.path.Tangent(Mathf.Max(0,route.ends[k-1]-80)));choice.SendMessage("Update");var observed=choice.CaptureLive();Check(observed.observing&&observed.pedestrian!=null,"PS09 pedestrian fixture observed before save");observed.pedestrian.started=true;observed.pedestrian.elapsed=2.5f;choice.RestoreLive(observed);laws=s.law.ledger.Count;state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));j.RestoreLive(state);var resumed=choice.CaptureLive();Check(resumed.observing&&resumed.pedestrian.started&&resumed.pedestrian.elapsed==2.5f,"PS09 pedestrian timer restored without restart or extra elapsed tick");Check(s.law.ledger.Count==laws,"PS09 restoring observation does not duplicate law event");
 }
}
